// RFID lab R4 Inside the card.  uv run pio run -d labs/rfid-lab-r4 -e rfid-lab-r4 -t upload
// The card's memory: sectors, trailers, access bits, authentication with the factory key.
//
// Wiring: the screen from lesson 03, plus the RC522 (3.3V only):
//   SDA->15  SCK->16  MOSI->17  MISO->18  IRQ->13 (optional)  GND->GND  RST->14  3.3V->3V3
// The push button on GPIO 5 is optional: it does exactly what BOOT does.
//
// Views: chip · card · trace · memory   (button: click = next, double-click = the action in the footer)
// Serial: help lists this lab's commands. The shared code is in kit/lib/rfid-lab-kit and kit/lib/rfid-kit.
#include "lab_commands.h"

namespace {

const LabView kViews[] = {
    {View::Chip, "selftest"},
    {View::Card, "inventory"},
    {View::Trace, "trace"},
    {View::Memory, "dump"},
};

const LabCommand kCommands[] = {labcmd::kChip, labcmd::kReset, labcmd::kSelftest, labcmd::kLoopback, labcmd::kRegs, labcmd::kSpi, labcmd::kGain, labcmd::kTimeout, labcmd::kIrq, labcmd::kPoll, labcmd::kTrace, labcmd::kInventory, labcmd::kDump, labcmd::kRead};

const LabSpec kSpec{"rfid-lab-r4", "R4 Inside the card", kViews, sizeof(kViews) / sizeof(kViews[0]), 3,
                    kCommands, sizeof(kCommands) / sizeof(kCommands[0])};

Lab lab(kSpec);

}  // namespace

void setup() { lab.begin(); }

void loop() { lab.loop(); }

// Every serial command of the RFID labs, ready to be listed in a lab's LabSpec. A lab includes
// the ones its lesson teaches; R6 has them all. Each one checks its arguments here, on loop(),
// then hands a job to the reader task: the chip is only ever touched by that task.
#pragma once

#include "lab.h"

namespace labcmd {

using J = Reader::Job;

// ---- R1: the chip ------------------------------------------------------------------------------

inline void chip(Lab &lab, const String &, const String &) { lab.submit(J::Chip); }
inline void reset(Lab &lab, const String &, const String &) { lab.submit(J::Reset); }
inline void selftest(Lab &lab, const String &, const String &) {
  lab.showView(View::Chip);
  lab.submit(J::SelfTest);
}
inline void loopback(Lab &lab, const String &, const String &) { lab.submit(J::Loopback); }
inline void regs(Lab &lab, const String &, const String &) { lab.submit(J::Regs); }
inline void spi(Lab &lab, const String &arg, const String &) {
  long n = 0;
  if (!Lab::number(arg, 1, 40, n)) return lab.warn("spi <MHz>, 1-40 (the chip is rated for 10)");
  lab.submit(J::Spi, n);
}
inline void gain(Lab &lab, const String &arg, const String &) {
  long n = 0;
  if (!Lab::number(arg, 0, 7, n)) return lab.warn("gain <0-7>: 0=18 1=23 4=33 5=38 6=43 7=48 dB");
  lab.submit(J::Gain, n);
}
inline void timeout(Lab &lab, const String &arg, const String &) {
  long n = 0;
  if (!Lab::number(arg, 25, 1'000'000, n)) return lab.warn("timeout <us>, 25-1000000 (default 25000)");
  lab.submit(J::Timeout, n);
}
inline void irq(Lab &lab, const String &, const String &lower) {
  if (lower != "on" && lower != "off") return lab.warn("irq on | irq off");
  lab.submit(J::Irq, lower == "on");
}

constexpr LabCommand kChip{"chip", "", "read VersionReg again (92h NXP, B2h/88h clones, 00/FF = no answer)", chip};
constexpr LabCommand kReset{"reset", "", "hard reset of the reader chip (RST pin), then VersionReg", reset};
constexpr LabCommand kSelftest{"selftest", "", "the datasheet's digital self-test (clones: two runs compared)", selftest};
constexpr LabCommand kLoopback{"loopback", "", "3,200 bytes through the chip's FIFO and back", loopback};
constexpr LabCommand kRegs{"regs", "", "15 registers with their bits and meaning", regs};
constexpr LabCommand kSpi{"spi", "<MHz>", "SPI clock, 1-40 (default 4, the chip's limit is 10)", spi};
constexpr LabCommand kGain{"gain", "<0-7>", "receiver gain, 18-48 dB (default 4 = 33 dB)", gain};
constexpr LabCommand kTimeout{"timeout", "<us>", "how long the chip waits for a card (default 25000)", timeout};
constexpr LabCommand kIrq{"irq", "on|off", "wait on the IRQ wire, or poll the chip over SPI", irq};

// ---- R2: the field and the sniffer -------------------------------------------------------------

inline void poll(Lab &lab, const String &, const String &lower) {
  if (lower != "on" && lower != "off") return lab.warn("poll on | poll off");
  lab.submit(J::Poll, lower == "on");
}
// `trace` alone toggles (the trace view's double-click), `trace on|off` sets.
inline void trace(Lab &lab, const String &, const String &lower) {
  if (!lower.isEmpty() && lower != "on" && lower != "off") return lab.warn("trace | trace on | trace off");
  const bool on = lower.isEmpty() ? !lab.traceOn() : lower == "on";
  lab.setTraceOn(on);
  lab.submit(J::Trace, on);
}

constexpr LabCommand kPoll{"poll", "on|off", "look for cards ~12 times a second, or pause", poll};
constexpr LabCommand kTrace{"trace", "[on|off]", "the sniffer: print each card's frames (alone: toggle)", trace};

// ---- R3: two cards at once ---------------------------------------------------------------------

inline void inventory(Lab &lab, const String &, const String &) { lab.submit(J::Inventory); }
constexpr LabCommand kInventory{"inventory", "", "find every card in the field, one by one", inventory};

// ---- R4: the card's memory ---------------------------------------------------------------------

inline void dump(Lab &lab, const String &, const String &) {
  lab.showView(View::Memory);
  lab.submit(J::Dump);
}
inline void read(Lab &lab, const String &arg, const String &) {
  long n = 0;
  if (!Lab::number(arg, 0, 63, n)) return lab.warn("read <block>, 0-63");
  lab.submit(J::Read, n);
}

constexpr LabCommand kDump{"dump", "", "all 16 sectors with the factory key (hold the card still)", dump};
constexpr LabCommand kRead{"read", "<block>", "one block, 0-63", read};

// ---- R5: write and count -----------------------------------------------------------------------

inline void write(Lab &lab, const String &arg, const String &) {
  const int sp = arg.indexOf(' ');
  long n = 0;
  if (sp < 0 || !Lab::number(arg.substring(0, sp), 1, 63, n)) return lab.warn("write <block> <text>, e.g. write 4 hello bench");
  lab.submit(J::Write, n, arg.substring(sp + 1).c_str());
}
inline void credits(Lab &lab, const String &arg, const String &lower) {
  lab.showView(View::Credits);
  if (arg.isEmpty()) return lab.submit(J::Credits);
  const int sp = lower.indexOf(' ');
  const String op = sp < 0 ? lower : lower.substring(0, sp);
  long n = 0;
  if (sp < 0 || !Lab::number(lower.substring(sp + 1), 0, 100000, n)) return lab.warn("credits init|add|use <n>, 0-100000");
  if (op == "init") return lab.submit(J::CreditsInit, n);
  if (op == "add") return lab.submit(J::CreditsAdd, n);
  if (op == "use") return lab.submit(J::CreditsUse, n);
  lab.warn("credits init|add|use <n>");
}

constexpr LabCommand kWrite{"write", "<block> <text>", "16 bytes of text into a data block, read back", write};
constexpr LabCommand kCredits{"credits", "[init|add|use <n>]", "a value block on block 8, backup on 9", credits};

// ---- R6: the edge lab --------------------------------------------------------------------------

inline void edge(Lab &lab, const String &, const String &lower) {
  static const J kOrder[] = {J::EdgeSpi, J::EdgeGain, J::EdgeTimeout, J::EdgeTiming, J::EdgeIrq, J::EdgeCrc, J::EdgeStress};
  lab.showView(View::Edge);
  const int sp = lower.indexOf(' ');
  const String what = sp < 0 ? lower : lower.substring(0, sp);
  if (what == "next") return lab.submit(kOrder[lab.takeNextEdge()], 200);
  if (what == "spi") return lab.submit(J::EdgeSpi);
  if (what == "gain") return lab.submit(J::EdgeGain);
  if (what == "timeout") return lab.submit(J::EdgeTimeout);
  if (what == "timing") return lab.submit(J::EdgeTiming);
  if (what == "irq") return lab.submit(J::EdgeIrq);
  if (what == "crc") return lab.submit(J::EdgeCrc);
  if (what == "stress") {
    long n = 200;
    if (sp >= 0 && !Lab::number(lower.substring(sp + 1), 10, 5000, n)) return lab.warn("edge stress [10-5000]");
    return lab.submit(J::EdgeStress, n);
  }
  lab.warn("edge spi | gain | timeout | timing | irq | crc | stress [n] | next");
}

constexpr LabCommand kEdge{"edge", "<test>", "spi gain timeout timing irq crc stress [n], or next", edge};

}  // namespace labcmd

// The shell every RFID lab (R1-R6) shares: the screen, the push button and BOOT, the on-board
// LED, serial input, and the reader task that owns the RC522.
//
// A lab is a LabSpec: which screen views it has (and what a double-click does on each), and which
// serial commands it understands. Each src/rfid-lab-rN/main.cpp is just that list, so every lab's
// `help` shows exactly what that lesson teaches.
//
// Button or BOOT: click = next view · double-click = this view's action · long press = pause polling
// On-board LED: bright green flash = a card was just read · steady green = a card is on the reader ·
//               red = the reader chip isn't answering (wiring) · off = no card
#pragma once

#include <Arduino.h>

#include "button.h"
#include "color.h"
#include "display.h"
#include "pins.h"
#include "reader.h"
#include "rfid_views.h"

enum class View : uint8_t { Chip, Card, Trace, Memory, Credits, Edge };

inline const char *viewName(View v) {
  static const char *const names[] = {"chip", "card", "trace", "memory", "credits", "edge"};
  return names[static_cast<int>(v)];
}

class Lab;

struct LabCommand {
  const char *name;  // the first word you type
  const char *args;  // for help, e.g. "<block> <text>"
  const char *what;  // one line for help
  void (*run)(Lab &lab, const String &arg, const String &lower);
};

struct LabView {
  View view;
  const char *action;  // the command line a double-click runs on this view, or nullptr
};

struct LabSpec {
  const char *env;    // "rfid-lab-r1"
  const char *title;  // "R1 Wire & talk"
  const LabView *views;
  int viewCount;
  int startView;
  const LabCommand *commands;
  int commandCount;
};

class Lab {
 public:
  explicit Lab(const LabSpec &spec) : spec_(spec), view_(spec.startView) {}

  void begin() {
    Serial.begin(115200);
    delay(1500);
    if (!display_.begin()) {
      log_e("No memory for the frame buffer. Stopping.");
      return;
    }
    rgbLedWrite(PIN_RGB, 0, 0, 0);
    external_.begin();
    boot_.begin();
    reader_.begin();
    log_i("%s: reader task started on core 0, screen on core %d", spec_.env, xPortGetCoreID());
    printHelp();
  }

  void loop() {
    FrameBuffer &fb = display_.fb();
    if (fb.pixels() == nullptr) {
      delay(1000);
      return;
    }
    pollSerial();
    handleButton(external_);
    handleButton(boot_);
    const uint32_t readsBefore = snap_.reads;
    reader_.update(snap_);
    showLed(snap_.reads != readsBefore);

    const float t = millis() / 1000.0f;
    const LabView &v = spec_.views[view_];
    fb.fillScreen(pal::night);
    switch (v.view) {
      case View::Chip: rv::chip(fb, snap_, t); break;
      case View::Card: rv::card(fb, snap_, t); break;
      case View::Trace: rv::trace(fb, reader_.trace(), traceOn_); break;
      case View::Memory: rv::memory(fb, snap_, t); break;
      case View::Credits: rv::credits(fb, snap_, t); break;
      case View::Edge: rv::edgeChart(fb, snap_); break;
    }
    char hint[48];
    if (v.action) snprintf(hint, sizeof(hint), "double-click: %s", v.action);
    else snprintf(hint, sizeof(hint), "click: next view");
    rv::header(fb, viewName(v.view), view_, spec_.viewCount, snap_);
    rv::footer(fb, hint, snap_);
    display_.push();
  }

  // ---- For the command handlers (lab_commands.h) ----------------------------------------------

  void submit(Reader::Job job, int32_t a = 0, const char *text = "") {
    Reader::Request r{job, a};
    strlcpy(r.text, text, sizeof(r.text));
    if (!reader_.submit(r)) log_w("the reader is busy with 4 jobs already, try again in a moment");
  }

  // log_w is a macro that can't be returned from a void function; this can.
  [[gnu::format(printf, 2, 3)]] void warn(const char *fmt, ...) {
    char text[96];
    va_list ap;
    va_start(ap, fmt);
    vsnprintf(text, sizeof(text), fmt, ap);
    va_end(ap);
    log_w("%s", text);
  }

  // Switch to a view if this lab has it (dump shows the memory view, and so on).
  void showView(View v) {
    for (int i = 0; i < spec_.viewCount; i++)
      if (spec_.views[i].view == v) return setView(i);
  }

  bool traceOn() const { return traceOn_; }
  void setTraceOn(bool on) { traceOn_ = on; }
  const Snapshot &snap() const { return snap_; }
  int takeNextEdge() {
    const int e = nextEdge_;
    nextEdge_ = (nextEdge_ + 1) % 7;
    return e;
  }

  // Parse a number argument; false when it is missing, not a number or out of range.
  static bool number(const String &arg, long lo, long hi, long &out) {
    if (arg.isEmpty()) return false;
    for (size_t i = 0; i < arg.length(); i++)
      if (!isDigit(arg[i]) && !(i == 0 && arg[i] == '-')) return false;
    out = arg.toInt();
    return out >= lo && out <= hi;
  }

  void runLine(const String &raw) {
    String line = raw;
    line.trim();
    if (line.isEmpty()) return;
    const int sp = line.indexOf(' ');
    String cmd = sp < 0 ? line : line.substring(0, sp);
    String arg = sp < 0 ? String() : line.substring(sp + 1);
    cmd.toLowerCase();
    arg.trim();
    String lower = arg;
    lower.toLowerCase();
    if (cmd == "help" || cmd == "?") return printHelp();
    if (cmd == "view") {
      long n = 0;
      if (!number(arg, 1, spec_.viewCount, n)) return warn("view <1-%d>", spec_.viewCount);
      return setView(n - 1);
    }
    for (int i = 0; i < spec_.commandCount; i++)
      if (cmd == spec_.commands[i].name) return spec_.commands[i].run(*this, arg, lower);
    log_w("unknown command '%s' in %s (type help)", line.c_str(), spec_.env);
  }

 private:
  void printHelp() {
    Serial.printf("\nRFID lab %s  (%s)\n", spec_.title, spec_.env);
    for (int i = 0; i < spec_.commandCount; i++) {
      const LabCommand &c = spec_.commands[i];
      char usage[40];
      snprintf(usage, sizeof(usage), "%s %s", c.name, c.args);
      Serial.printf("  %-28s %s\n", usage, c.what);
    }
    Serial.printf("  %-28s %s\n", "view <n>", "show screen view n");
    Serial.print("Views:");
    for (int i = 0; i < spec_.viewCount; i++)
      Serial.printf(" %d %s%s", i + 1, viewName(spec_.views[i].view), i + 1 < spec_.viewCount ? " ·" : "\n");
    Serial.println("Button (GPIO 5, optional) or BOOT: click = next view, double-click = the view's action, long = pause polling");
  }

  void setView(int v) {
    view_ = (v % spec_.viewCount + spec_.viewCount) % spec_.viewCount;
    log_i("view %d: %s", view_ + 1, viewName(spec_.views[view_].view));
  }

  void pollSerial() {
    static String buffer;
    while (Serial.available()) {
      const char c = Serial.read();
      if (c == '\n' || c == '\r') {
        if (!buffer.isEmpty()) runLine(buffer);
        buffer = "";
      } else if (c == 0x08 || c == 0x7F) {
        // Backspace: the monitor sends it as a character; without this, "chiq<BS>p" would arrive as is.
        if (!buffer.isEmpty()) buffer.remove(buffer.length() - 1);
      } else if (uint8_t(c) < 0x20) {
        // Other control characters (arrow keys send escape sequences): ignore.
      } else if (buffer.length() < 96) {
        buffer += c;
      }
    }
  }

  void handleButton(Button &b) {
    switch (b.poll()) {
      case Button::Event::Click: setView(view_ + 1); break;
      case Button::Event::DoubleClick:
        if (spec_.views[view_].action) {
          Serial.printf("> %s   (double-click)\n", spec_.views[view_].action);
          runLine(spec_.views[view_].action);
        }
        break;
      case Button::Event::LongPress: submit(Reader::Job::Poll, !snap_.polling); break;
      case Button::Event::None: break;
    }
  }

  // The on-board LED says what the reader sees. Sent only when the colour changes: each write is a
  // whole WS2812 frame on GPIO 48.
  void showLed(bool justRead) {
    if (justRead) flashUntil_ = millis() + 300;
    // version 0 = the reader task hasn't reported yet (the first ~50 ms after power-on): not "silent".
    const bool chipSilent = snap_.version != 0 && (snap_.chipVersion == 0x00 || snap_.chipVersion == 0xFF);
    uint8_t r = 0, g = 0, b = 0;
    if (chipSilent) r = 90;                                    // red: the reader chip isn't answering
    else if (millis() < flashUntil_) r = 40, g = 220, b = 70;  // bright green flash: a card was just read
    else if (snap_.present) g = 90, b = 25;                    // steady green: a card is on the reader
    const uint32_t colour = (uint32_t(r) << 16) | (uint32_t(g) << 8) | b;
    if (colour == ledShown_) return;
    ledShown_ = colour;
    rgbLedWrite(PIN_RGB, r, g, b);
  }

  const LabSpec &spec_;
  Display display_;
  Reader reader_;
  Button external_{PIN_BUTTON, "button"};
  Button boot_{PIN_BOOT_BTN, "BOOT"};
  Snapshot snap_;
  int view_;
  bool traceOn_ = true;
  int nextEdge_ = 0;
  uint32_t flashUntil_ = 0, ledShown_ = 0xFFFFFFFF;
};

// A push button on any GPIO, wired between the pin and GND.
//
// Wiring: we turn on the chip's internal pull-up resistor, so the pin reads HIGH when the
// button is up and LOW when pressed (the button connects it to GND). No resistor needed.
//
// Bounce: the metal contacts inside a button flicker on/off for a few milliseconds on
// every press and release. Our screen loop only looks about 22 times a second, far too
// slowly to see that. So an interrupt counts every single edge the instant it happens,
// and poll() only trusts a new state once the pin has been quiet for kDebounceMs.
//
// Gestures, reported by poll():
//   Click        press and release, then nothing else for kDoubleGapMs
//   DoubleClick  two clicks within kDoubleGapMs
//   LongPress    held for kLongPressMs (fires while still held, so it feels instant)
#pragma once

#include <Arduino.h>
#include <esp_timer.h>

class Button {
 public:
  enum class Event { None, Click, DoubleClick, LongPress };

  Button(uint8_t pin, const char *name) : pin_(pin), name_(name) {}

  void begin() {
    pinMode(pin_, INPUT_PULLUP);
    // CHANGE = run onEdge on every rising and falling edge, bounces included.
    attachInterruptArg(digitalPinToInterrupt(pin_), onEdge, this, CHANGE);
  }

  const char *name() const { return name_; }
  bool isDown() const { return pressed_; }
  // Raw edges seen during the last press + release, minus the 2 a perfect button makes.
  uint32_t lastBounces() const { return lastBounces_; }

  Event poll() {
    const uint32_t nowUs = uint32_t(esp_timer_get_time());
    const uint32_t now = millis();

    // 1. Debounce: accept the pin's level once no edge has arrived for kDebounceMs.
    const bool level = digitalRead(pin_) == LOW;
    if (level != pressed_ && nowUs - lastEdgeUs_ >= kDebounceMs * 1000) {
      pressed_ = level;
      if (pressed_) {
        pressedAt_ = now;
        longFired_ = false;
      } else {
        // Every edge since the previous release belongs to this press + release.
        const uint32_t edges = edges_ - edgesAtRest_;
        edgesAtRest_ = edges_;
        lastBounces_ = edges > 2 ? edges - 2 : 0;
        if (!longFired_) {
          clicks_++;
          releasedAt_ = now;
        }
      }
    }

    // 2. Turn clean presses into gestures.
    if (pressed_ && !longFired_ && now - pressedAt_ >= kLongPressMs) {
      longFired_ = true;
      clicks_ = 0;
      return Event::LongPress;
    }
    if (!pressed_ && clicks_ >= 2) {
      clicks_ = 0;
      return Event::DoubleClick;
    }
    if (!pressed_ && clicks_ == 1 && now - releasedAt_ >= kDoubleGapMs) {
      clicks_ = 0;
      return Event::Click;
    }
    return Event::None;
  }

 private:
  static constexpr uint32_t kDebounceMs = 25;
  static constexpr uint32_t kLongPressMs = 600;
  static constexpr uint32_t kDoubleGapMs = 280;

  // Runs inside the interrupt: keep it tiny. IRAM_ATTR keeps it in fast internal RAM.
  static void IRAM_ATTR onEdge(void *arg) {
    auto *self = static_cast<Button *>(arg);
    self->edges_ = self->edges_ + 1;
    self->lastEdgeUs_ = uint32_t(esp_timer_get_time());  // 32 bits: read in one go, wraps safely
  }

  uint8_t pin_;
  const char *name_;
  volatile uint32_t edges_ = 0;      // written by the interrupt
  volatile uint32_t lastEdgeUs_ = 0;  // written by the interrupt
  bool pressed_ = false;
  bool longFired_ = false;
  uint8_t clicks_ = 0;
  uint32_t edgesAtRest_ = 0;
  uint32_t lastBounces_ = 0;
  uint32_t pressedAt_ = 0;
  uint32_t releasedAt_ = 0;
};

// Colour helpers for the 16-bit RGB565 format the ST7789 speaks: 5 bits red, 6 green, 5 blue.
#pragma once

#include <stdint.h>

constexpr uint16_t rgb(uint8_t r, uint8_t g, uint8_t b) {
  return uint16_t(((r & 0xF8) << 8) | ((g & 0xFC) << 3) | (b >> 3));
}

// Hue 0-255 around the colour wheel, saturation and value 0-255.
inline uint16_t hsv(uint8_t h, uint8_t s, uint8_t v) {
  const uint8_t region = h / 43;
  const uint8_t rem = (h - region * 43) * 6;
  const uint8_t p = (v * (255 - s)) >> 8;
  const uint8_t q = (v * (255 - ((s * rem) >> 8))) >> 8;
  const uint8_t t = (v * (255 - ((s * (255 - rem)) >> 8))) >> 8;
  switch (region) {
    case 0: return rgb(v, t, p);
    case 1: return rgb(q, v, p);
    case 2: return rgb(p, v, t);
    case 3: return rgb(p, q, v);
    case 4: return rgb(t, p, v);
    default: return rgb(v, p, q);
  }
}

// Mix two colours: k = 0 gives a, k = 255 gives b.
inline uint16_t mix(uint16_t a, uint16_t b, uint8_t k) {
  const int ar = a >> 11, ag = (a >> 5) & 63, ab = a & 31;
  const int br = b >> 11, bg = (b >> 5) & 63, bb = b & 31;
  return uint16_t(((ar + ((br - ar) * k >> 8)) << 11) | ((ag + ((bg - ag) * k >> 8)) << 5) | (ab + ((bb - ab) * k >> 8)));
}

// The palette every scene shares, so the showcase reads as one piece.
namespace pal {
constexpr uint16_t ink = rgb(232, 238, 246);
constexpr uint16_t muted = rgb(118, 138, 162);
constexpr uint16_t dim = rgb(34, 46, 62);
constexpr uint16_t night = rgb(10, 14, 22);
constexpr uint16_t teal = rgb(70, 220, 190);
constexpr uint16_t amber = rgb(255, 176, 60);
constexpr uint16_t coral = rgb(255, 96, 84);
}  // namespace pal

// The 1.9" ST7789 screen plus an off-screen frame buffer, set up the way every lesson since 03 uses it.
// Draw into fb() with the normal Adafruit GFX calls, then push() sends the whole picture at once.
#pragma once

#include <Adafruit_ST7789.h>
#include <SPI.h>

#include "frame_buffer.h"
#include "pins.h"

class Display {
 public:
  static constexpr int16_t kW = 320, kH = 170;  // landscape

  Display() : tft_(&SPI, PIN_TFT_CS, PIN_TFT_DC, PIN_TFT_RST), fb_(kW, kH) {}

  // Returns false if there is no memory for the frame buffer.
  bool begin(uint32_t spiHz = 40'000'000) {
    // Backlight through PWM so it can be dimmed (setBacklight). Full brightness to start.
    ledcAttach(PIN_TFT_BL, 5000, 8);
    ledcWrite(PIN_TFT_BL, 255);
    SPI.begin(PIN_TFT_SCLK, -1, PIN_TFT_MOSI, PIN_TFT_CS);
    tft_.init(170, 320);
    tft_.setSPISpeed(spiHz);
    tft_.setRotation(1);
    tft_.fillScreen(0);
    return fb_.begin();
  }

  FrameBuffer &fb() { return fb_; }
  // 0 = off, 255 = full brightness.
  void setBacklight(uint8_t level) { ledcWrite(PIN_TFT_BL, level); }
  void push() { tft_.drawRGBBitmap(0, 0, fb_.pixels(), kW, kH); }

 private:
  Adafruit_ST7789 tft_;
  FrameBuffer fb_;
};

